from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')

css_anchor='.data-table tr.selected{background:rgba(49,230,161,.07)}'
css_add=r'''.candidate-audit-intro{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;padding:12px 13px;margin-bottom:12px;border:1px solid rgba(57,189,248,.22);border-radius:12px;background:rgba(57,189,248,.05)}.candidate-audit-intro p{margin:3px 0 0;color:var(--muted);font-size:.72rem}.candidate-path-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin:0 0 12px}.candidate-path-item{padding:10px;border:1px solid rgba(84,127,150,.22);border-radius:10px;background:rgba(5,15,21,.32);min-width:0}.candidate-path-item small{display:block;color:var(--dim);font-size:.55rem;letter-spacing:.08em;text-transform:uppercase}.candidate-path-item b{display:block;margin-top:4px;font-size:.7rem;overflow-wrap:anywhere}.candidate-path-item.favourite{border-color:rgba(49,230,161,.38);background:rgba(49,230,161,.055)}.candidate-path-item.favourite b{color:var(--accent)}.candidate-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:10px}.candidate-audit-card{padding:13px;border:1px solid rgba(84,127,150,.24);border-radius:13px;background:linear-gradient(180deg,rgba(15,30,38,.92),rgba(8,18,24,.9));min-width:0}.candidate-audit-card.selected{border-color:rgba(49,230,161,.5);box-shadow:inset 0 2px 0 rgba(49,230,161,.48)}.candidate-audit-card.low{box-shadow:inset 0 2px 0 rgba(255,200,87,.65)}.candidate-audit-head{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.candidate-audit-head h4{margin:0;font-size:.82rem;line-height:1.3}.candidate-score{min-width:35px;text-align:center;padding:5px 7px;border:1px solid rgba(49,230,161,.28);border-radius:9px;color:var(--accent);font:850 .72rem var(--mono);background:rgba(49,230,161,.055)}.candidate-role-tags{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}.candidate-facts{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:10px}.candidate-fact{padding:7px 8px;border:1px solid rgba(84,127,150,.16);border-radius:8px;background:rgba(0,0,0,.12);min-width:0}.candidate-fact small{display:block;color:var(--dim);font-size:.53rem;text-transform:uppercase;letter-spacing:.07em}.candidate-fact b{display:block;margin-top:2px;font:700 .67rem var(--mono);overflow-wrap:anywhere}.candidate-penalties{display:flex;gap:5px;flex-wrap:wrap;margin-top:9px}.candidate-rationale{margin-top:12px;display:grid;gap:7px}.candidate-rationale div{padding:9px 10px;border-left:2px solid rgba(57,189,248,.42);background:rgba(57,189,248,.045);border-radius:0 8px 8px 0}.candidate-rationale small{display:block;color:var(--dim);font-size:.55rem;text-transform:uppercase}.candidate-rationale span{display:block;color:var(--muted);font-size:.69rem;margin-top:2px}.candidate-full-table{margin-top:12px}.candidate-full-table summary{padding:10px 0!important;color:var(--muted);font-size:.7rem}.candidate-path-fallback{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.candidate-path-card{padding:13px;border:1px solid rgba(84,127,150,.23);border-radius:12px;background:rgba(5,15,21,.3)}.candidate-path-card.favourite{border-color:rgba(49,230,161,.38);background:rgba(49,230,161,.05)}.candidate-path-card small{display:block;color:var(--dim);font-size:.56rem;text-transform:uppercase;letter-spacing:.08em}.candidate-path-card strong{display:block;margin-top:4px;font-size:.84rem}.candidate-path-card p{margin:7px 0 0;color:var(--muted);font-size:.68rem}.candidate-match-basis{margin-top:11px;padding:10px 11px;border:1px solid rgba(84,127,150,.18);border-radius:10px}.candidate-match-basis small{display:block;color:var(--dim);font-size:.56rem;text-transform:uppercase}.candidate-match-basis p{margin:4px 0 0;color:var(--muted);font-size:.7rem}@media(max-width:760px){.candidate-path-strip{grid-template-columns:1fr 1fr}.candidate-path-fallback{grid-template-columns:1fr}.candidate-facts{grid-template-columns:1fr 1fr}}'''
if s.count(css_anchor)!=1: raise SystemExit(f'css anchor count={s.count(css_anchor)}')
s=s.replace(css_anchor,css_anchor+css_add,1)

start=s.index('function candidateTable(m){')
end=s.index('\n\nfunction radarPredicate',start)
old=s[start:end]
if 'Keine Kandidaten gespeichert.' not in old: raise SystemExit('unexpected candidateTable source')

new=r'''function candidateAuditRoot(m){return firstObject(m.candidate_audit,obj(m.decision_engine).candidate_audit,obj(m.decision_engine_output).candidate_audit,obj(m.candidate_review))}
function candidateList(m){const audit=candidateAuditRoot(m),sets=[audit.candidates_structured,m.candidates,audit.prediction_map_rendered,m.prediction_map];for(const set of sets){if(arr(set).length)return arr(set).map(x=>typeof x==='string'?{prediction:x}:x)}return []}
function candidateName(x){return x?.expression??x?.prediction??x?.name??x?.candidate??null}
function candidateAxis(x){return x?.axis??x?.market_axis??null}
function candidateWorld(x){return x?.world??x?.supported_world??x?.scenario??null}
function candidateScore(x){return x?.score_total??x?.score??null}
function candidateWFRD(x){if(present(x?.W_F_R_D))return x.W_F_R_D;if([x?.W,x?.F,x?.R,x?.D].every(v=>v!==undefined&&v!==null))return `${x.W}/${x.F}/${x.R}/${x.D}`;return null}
function candidatePenalties(x){return [...arr(x?.penalties),...arr(x?.flags)]}
function decisionPathInfo(m,key){const d=obj(obj(m.decision_paths)[key]);const direct=m[key];return {expression:d.expression??d.prediction??direct??null,rationale:d.rationale??d.reason??null}}
function candidateFavourite(m){const fd=obj(m.favourite_decision);return fd.favourite_prediction??fd.favourite??fav(m)}
function candidateNorm(v){return String(v??'').trim().toLowerCase().replace(/\s+/g,' ')}
function candidateRoles(m,name){const n=candidateNorm(name),roles=[];[['SAFE',decisionPathInfo(m,'safe').expression],['BALANCED',decisionPathInfo(m,'balanced').expression],['AGGRESSIVE',decisionPathInfo(m,'aggressive').expression],['FAVOURITE',candidateFavourite(m)]].forEach(([k,v])=>{if(n&&n===candidateNorm(v))roles.push(k)});return roles}
function candidatePathStrip(m){const rows=[['SAFE',decisionPathInfo(m,'safe').expression],['BALANCED',decisionPathInfo(m,'balanced').expression],['AGGRESSIVE',decisionPathInfo(m,'aggressive').expression],['FAVOURITE',candidateFavourite(m)]];return `<div class="candidate-path-strip">${rows.map(([k,v])=>`<div class="candidate-path-item ${k==='FAVOURITE'?'favourite':''}"><small>${k}</small><b>${show(v)}</b></div>`).join('')}</div>`}
function candidateRationales(m){const rows=[['SAFE',decisionPathInfo(m,'safe').rationale],['BALANCED',decisionPathInfo(m,'balanced').rationale],['AGGRESSIVE',decisionPathInfo(m,'aggressive').rationale],['FAVOURITE',m.favourite_decision_reason||obj(m.favourite_decision).reason||m.reason]] .filter(([,v])=>present(v));return rows.length?`<div class="candidate-rationale">${rows.map(([k,v])=>`<div><small>${k} · Begründung</small><span>${show(v)}</span></div>`).join('')}</div>`:''}
function candidateFullAudit(m,cands){const cards=cands.map(x=>{const name=candidateName(x),roles=candidateRoles(m,name),low=String(x.robustness||'').toUpperCase()==='LOW',pen=candidatePenalties(x),praw=present(x.p_raw)?`${x.p_raw}${typeof x.p_raw==='number'?'%':''}`:null;return `<article class="candidate-audit-card ${roles.includes('FAVOURITE')?'selected':''} ${low?'low':''}"><div class="candidate-audit-head"><h4>${show(name)}</h4><span class="candidate-score">${show(candidateScore(x))}</span></div>${roles.length?`<div class="candidate-role-tags">${roles.map(r=>`<span class="chip ${r==='FAVOURITE'?'green':'blue'}">${r}</span>`).join('')}</div>`:''}<div class="candidate-facts"><div class="candidate-fact"><small>Achse</small><b>${show(candidateAxis(x))}</b></div><div class="candidate-fact"><small>Szenario</small><b>${show(candidateWorld(x))}</b></div><div class="candidate-fact"><small>Abdeckung</small><b>${show(x.cluster_coverage)}</b></div><div class="candidate-fact"><small>p_raw</small><b>${show(praw)}</b></div><div class="candidate-fact"><small>W/F/R/D</small><b>${show(candidateWFRD(x))}</b></div><div class="candidate-fact"><small>Robustheit</small><b>${show(x.robustness)}</b></div><div class="candidate-fact"><small>Status</small><b>${show(x.status)}</b></div><div class="candidate-fact"><small>Score</small><b>${show(candidateScore(x))}</b></div></div>${pen.length?`<div class="candidate-penalties">${pen.map(v=>`<span class="chip yellow">${show(v)}</span>`).join('')}</div>`:''}</article>`}).join('');const rows=cands.map(x=>`<tr><td>${show(candidateName(x))}</td><td>${show(candidateAxis(x))}</td><td>${show(candidateWorld(x))}</td><td>${show(x.cluster_coverage)}</td><td>${show(x.p_raw)}</td><td>${show(candidateWFRD(x))}</td><td>${show(candidateScore(x))}</td><td>${show(x.robustness)}</td><td>${candidatePenalties(x).length?candidatePenalties(x).map(show).join(' · '):'—'}</td><td>${show(x.status)}</td></tr>`).join('');return `<div class="candidate-audit-intro"><div><b>Vollständiger Kandidaten-Audit</b><p>${cands.length} gespeicherte Kandidaten. Die Bewertungsfelder werden direkt aus dem Run Record dargestellt und nicht vom Frontend neu berechnet.</p></div><span class="chip green">STRUCTURED</span></div>${candidatePathStrip(m)}<div class="candidate-grid">${cards}</div>${candidateRationales(m)}<details class="candidate-full-table"><summary>Vollständige Prüftabelle · W/F/R/D, p_raw, Abzüge und Status</summary><div class="table-wrap"><table class="data-table"><thead><tr><th>Kandidat</th><th>Achse</th><th>Szenario</th><th>Abdeckung</th><th>p_raw</th><th>W/F/R/D</th><th>Score</th><th>Robustheit</th><th>Abzüge</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table></div></details>`}
function candidatePathFallback(m){if(isNSP(m))return `<div class="candidate-audit-intro"><div><b>Kandidatenprüfung gesperrt</b><p>Für dieses Match wurde keine stabile Prediction freigegeben. Es werden keine Kandidatenwerte nachträglich konstruiert.</p></div><span class="chip yellow">NSP</span></div><div class="chips">${arr(m.nsp_codes).map(x=>`<span class="chip yellow">${show(x)}</span>`).join('')}</div>`;const paths=[['SAFE',decisionPathInfo(m,'safe')],['BALANCED',decisionPathInfo(m,'balanced')],['AGGRESSIVE',decisionPathInfo(m,'aggressive')],['FAVOURITE',{expression:candidateFavourite(m),rationale:m.favourite_decision_reason||obj(m.favourite_decision).reason||m.reason}]];const flags=arr(m.flags);const clusterText=arr(m.four_score_cluster).length?arr(m.four_score_cluster).join(' · '):null;return `<div class="candidate-audit-intro"><div><b>Entscheidungspfad-Prüfung</b><p>Dieser Run speichert keinen strukturierten Candidate Pool. Deshalb zeigt ECOBET die vier tatsächlich gespeicherten Entscheidungspfade, ohne p_raw, W/F/R/D, Candidate Score oder Robustheit zu erfinden.</p></div><span class="chip blue">PATH FALLBACK</span></div><div class="candidate-path-fallback">${paths.map(([k,d])=>`<div class="candidate-path-card ${k==='FAVOURITE'?'favourite':''}"><small>${k}</small><strong>${show(d.expression)}</strong><p>${present(d.rationale)?show(d.rationale):k==='SAFE'?'Gespeicherter Safe-Pfad.':k==='BALANCED'?'Gespeicherter Balanced-Pfad.':k==='AGGRESSIVE'?'Gespeicherter Aggressive-Pfad.':'Final gespeicherte Auswahl.'}</p></div>`).join('')}</div><div class="candidate-match-basis"><small>Gespeicherte Matchbasis</small><p>Ampel ${show(m.ampel)}${present(m.modal_score)?` · Modal ${show(m.modal_score)}`:''}${clusterText?` · Cluster ${show(clusterText)}`:''}</p>${flags.length?`<div class="candidate-penalties">${flags.map(v=>`<span class="chip yellow">${show(v)}</span>`).join('')}</div>`:''}</div>`}
function candidateTable(m){const cands=candidateList(m);return cands.length?candidateFullAudit(m,cands):candidatePathFallback(m)}'''
s=s[:start]+new+s[end:]

for marker in ['function candidateAuditRoot(m)','Vollständiger Kandidaten-Audit','Entscheidungspfad-Prüfung','PATH FALLBACK','W/F/R/D, p_raw, Abzüge und Status']:
    if marker not in s: raise SystemExit(f'missing marker {marker}')
p.write_text(s,encoding='utf-8')
